1: @import "tailwindcss";
2: 
3: :root {
4:   --background: #fafaf9; /* stone-50 */
5:   --foreground: #1c1917; /* stone-900 */
6:   --font-playfair: Georgia, "Times New Roman", serif;
7:   --font-outfit: Inter, Arial, sans-serif;
8: }
9: 
10: @theme inline {
11:   --color-background: var(--background);
12:   --color-foreground: var(--foreground);
13:   --font-serif: var(--font-playfair);
14:   --font-sans: var(--font-outfit);
15: }
16: 
17: /* UX round 2 (ux2-command-dialog-height-uncapped-confirm-unreachable): no modal dialog grows past the screen; its content
18:    scrolls inside it. A base-layer default, so a dialog's own max-height or overflow utility still wins; drawers (aside) keep
19:    their full height. */
20: @layer base {
21:   [role="dialog"][aria-modal="true"]:not(aside) {
22:     max-height: calc(100dvh - 2rem);
23:     overflow-y: auto;
24:   }
25: }
26: 
27: body {
28:   background: var(--background);
29:   color: var(--foreground);
30:   font-family: var(--font-outfit);
31: }
32: 
33: /* Arabic pages use IBM Plex Sans Arabic for body and display text (loaded via next/font). */
34: html[lang="ar"] {
35:   --font-outfit: var(--font-arabic), Inter, Arial, sans-serif;
36:   --font-playfair: var(--font-arabic), Georgia, serif;
37: }
38: 
