1: import type { Metadata } from "next";
2: import { IBM_Plex_Sans_Arabic } from "next/font/google";
3: import "./globals.css";
4: import { GlobalDevTools } from "@/components/global-dev-tools";
5: 
6: const arabicFont = IBM_Plex_Sans_Arabic({
7:   subsets: ["arabic", "latin"],
8:   weight: ["400", "500", "600", "700"],
9:   variable: "--font-arabic",
10:   display: "swap",
11: });
12: 
13: // Applies the visitor's saved language before first paint so Arabic pages never flash LTR.
14: // Pages keep reading document.documentElement.lang / dir, and their toggles keep writing primora_lang.
15: const languageBootstrap = `try{var l=localStorage.getItem("primora_lang");if(l==="ar"||l==="en"){var d=document.documentElement;d.lang=l;d.dir=l==="ar"?"rtl":"ltr";}}catch(e){}`;
16: 
17: export const metadata: Metadata = {
18:   title: "PRIMORA - Beauty & Grooming Marketplace",
19:   description: "Book beauty salons, barber shops, spas and wellness professionals across Saudi Arabia.",
20: };
21: 
22: export default function RootLayout({
23:   children,
24: }: Readonly<{
25:   children: React.ReactNode;
26: }>) {
27:   return (
28:     <html lang="en" dir="ltr" className={`h-full antialiased ${arabicFont.variable}`} suppressHydrationWarning>
29:       <head>
30:         <script dangerouslySetInnerHTML={{ __html: languageBootstrap }} />
31:       </head>
32:       <body className="min-h-full flex flex-col font-sans bg-stone-50 text-stone-900">
33:         {children}
34:         <GlobalDevTools />
35:       </body>
